mapper.select:
SELECT p.id, p.name, p.status, p.note, p.file_id, f.path AS image_url, p.created_at FROM templates p LEFT JOIN files f ON f.id = p.file_id
p.deleted_at IS NULL AND p.status = #{status}
AND (p.name ILIKE CONCAT('%', #{keyword}, '%') OR p.note ILIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.created_at DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE templates
SET status = #{status}, updated_by = #{updatedBy}
WHERE id = #{id}

UPDATE templates
SET deleted_at = now(), file_id = NULL, updated_by = #{updatedBy}
